async def act(page):
    """
    Locate the post "40 of our most helpful AI tips from 2025" using the
    site-visible search widget via the knowledge-base helper, navigate to the
    post, fill the comment "Great article!" and submit the comment form.

    Uses accessibility-role-centric selectors and checks counts before indexed
    access as required.
    """

    target_title = "40 of our most helpful AI tips from 2025"
    fallback_keywords = ["AI tips 2025", "AI tips"]

    # 1) Use the site-aware search helper to drive the visible search widget.
    #    This KB helper is appropriate for finding the post by title.
    try:
        results = await create_curated_collection_by_search(page, target_title, max_results=50, resolve_links=True)
    except Exception:
        results = None

    post_url = None
    if isinstance(results, (list, tuple)):
        for item in results:
            if not isinstance(item, dict):
                continue
            title = (item.get("title") or "").strip()
            url = item.get("url")
            if title and target_title.lower() in title.lower() and url:
                post_url = url
                break

    # 2) Fallback searches if exact title not returned
    if not post_url:
        for kw in fallback_keywords:
            try:
                res2 = await create_curated_collection_by_search(page, kw, max_results=50, resolve_links=True)
            except Exception:
                res2 = None
            if isinstance(res2, (list, tuple)):
                for item in res2:
                    if not isinstance(item, dict):
                        continue
                    title = (item.get("title") or "").strip()
                    url = item.get("url")
                    if title and "ai" in title.lower() and "2025" in title.lower() and url:
                        post_url = url
                        break
            if post_url:
                break

    # 3) Final fallback: scan visible links on current page (accessibility-role-centric)
    if not post_url:
        try:
            links = page.get_by_role("link")
            total = await links.count()
            for i in range(total):
                try:
                    l = links.nth(i)
                    txt = (await l.inner_text()).strip()
                    href = await l.get_attribute("href")
                    if href and (target_title.lower() in txt.lower() or ("ai tips" in txt.lower() and "2025" in txt.lower())):
                        post_url = href
                        break
                except Exception:
                    continue
        except Exception:
            pass

    if not post_url:
        # Could not find the target post; nothing more to do.
        return

    # 4) Navigate to the post page so we can interact with the comment form.
    await page.goto(post_url)
    await page.wait_for_load_state("networkidle")

    comment_text = "Great article!"

    # 5) Scope to <main> when available for more accurate selectors
    scope = page
    try:
        main_loc = page.get_by_role("main")
        if await main_loc.count() > 0:
            scope = main_loc
    except Exception:
        scope = page

    # 6) Try explicit textbox named 'Comment' inside scope
    filled = False
    try:
        comment_box = scope.get_by_role("textbox", name="Comment")
        if await comment_box.count() > 0:
            await comment_box.first.fill(comment_text)
            filled = True
    except Exception:
        filled = False

    # 7) Fallback: fill the last textbox in scope (common pattern for comment textarea)
    if not filled:
        try:
            textboxes = scope.get_by_role("textbox")
            tb_count = await textboxes.count()
            if tb_count > 0:
                chosen = None
                for i in range(tb_count):
                    try:
                        tb = textboxes.nth(i)
                        aria = None
                        try:
                            aria = await tb.get_attribute("aria-label")
                        except Exception:
                            aria = None
                        if aria and "comment" in aria.lower():
                            chosen = i
                            break
                    except Exception:
                        continue
                if chosen is None:
                    chosen = tb_count - 1
                await textboxes.nth(chosen).fill(comment_text)
                filled = True
        except Exception:
            filled = False

    if not filled:
        # No comment input found; stop.
        return

    # 8) Optionally fill Name/Email fields if present inside same scope
    try:
        if await scope.get_by_role("textbox", name="Name").count() > 0:
            await scope.get_by_role("textbox", name="Name").first.fill("Playwright Bot")
        elif await scope.get_by_role("textbox", name="Your name").count() > 0:
            await scope.get_by_role("textbox", name="Your name").first.fill("Playwright Bot")
    except Exception:
        pass

    try:
        if await scope.get_by_role("textbox", name="Email").count() > 0:
            await scope.get_by_role("textbox", name="Email").first.fill("bot@example.com")
        elif await scope.get_by_role("textbox", name="E-mail").count() > 0:
            await scope.get_by_role("textbox", name="E-mail").first.fill("bot@example.com")
    except Exception:
        pass

    # 9) Attempt to submit the comment using accessible buttons inside the scope
    submit_clicked = False
    for btn_name in ("Post Comment", "Submit Comment", "Submit", "Post", "Comment", "Send"):
        try:
            btn = scope.get_by_role("button", name=btn_name)
            if await btn.count() > 0:
                await btn.first.click()
                submit_clicked = True
                break
        except Exception:
            continue

    # 10) Last resort: click the last visible button in scope
    if not submit_clicked:
        try:
            buttons = scope.get_by_role("button")
            bcount = await buttons.count()
            if bcount > 0:
                await buttons.nth(bcount - 1).click()
                submit_clicked = True
        except Exception:
            pass

    return

